/* From Uiverse.io by reshades - Tags: button, hover, svg */
.__UIV_SCOPE__ .button {
  width: 10em;
  height: 3em;
  border-radius: 8px;
  border: 0.15em solid rgb(162, 63, 255);
  color: rgb(162, 63, 255);
  background-color: #00000000;
  transition: all 0.5s ease;
}

.__UIV_SCOPE__ .button .text {
  display: none
}

.__UIV_SCOPE__ .button:hover>.text {
  display: block;
}

.__UIV_SCOPE__ .button:hover>svg {
  display: none;
}

.__UIV_SCOPE__ .button:hover {
  background-color: rgb(162, 63, 255);
  color: #fff
}

.__UIV_SCOPE__ .button svg {
  width: 1.5em;
  margin-top: 3px;
}
